import React, { useEffect, useState } from "react";
import { fetchProfiles, sendFriendRequest } from "../api.js";
import "../styles/ProfileList.css";

const ProfileList = () => {
    const [profiles, setProfiles] = useState([]);  
    const [loading, setLoading] = useState(true);  
    const [error, setError] = useState(null);
    const [requestSent, setRequestSent] = useState({});
    const [notification, setNotification] = useState(null);

    useEffect(() => {
        const loadProfiles = async () => {
            try {
                const data = await fetchProfiles();
                setProfiles(data?.users || []); // Backend returns { users: [...] }
                setLoading(false);  
            } catch (err) {
                console.error("Failed to load profiles:", err);
                setError("Failed to load profiles. Please try again later.");  
                setLoading(false);
            }
        };
        loadProfiles();
    }, []); 

    const handleSendFriendRequest = async (userId) => {
        try {
            const response = await sendFriendRequest(userId);
            if (response.status === "Success") {
                // Update UI to show request sent
                setRequestSent(prev => ({
                    ...prev,
                    [userId]: true
                }));
                showNotification("Friend request sent!");
            }
        } catch (error) {
            console.error("Error sending friend request:", error);
            showNotification("Failed to send request", true);
        }
    };

    const showNotification = (message, isError = false) => {
        setNotification({ message, isError });
        setTimeout(() => setNotification(null), 3000);
    };

    if (loading) return <div className="profiles-loading">Loading profiles...</div>;
    if (error) return <div className="profiles-error">{error}</div>;
    if (!profiles || profiles.length === 0) return <div className="no-profiles">No profiles found. Check back later!</div>;

    return (
        <div className="profiles-container">
            {notification && (
                <div className={`notification ${notification.isError ? 'error' : 'success'}`}>
                    {notification.message}
                </div>
            )}

            <h1>Discover Artists</h1>
            <div className="profiles-grid">
                {profiles.map((profile) => (
                    <div key={profile.id} className="profile-card">
                        <div className="profile-image">
                            {/* Placeholder for profile image */}
                            <div className="profile-image-placeholder">
                                {profile.username ? profile.username.charAt(0).toUpperCase() : "?"}
                            </div>
                        </div>
                        <div className="profile-info">
                            <h3>{profile.username || "Anonymous User"}</h3>
                            <div className="profile-tags">
                                {profile.user_type && (
                                    <span className={`user-type-tag ${
                                        profile.user_type === "1" ? "producer" : 
                                        profile.user_type === "2" ? "musician" : 
                                        profile.user_type === "3" ? "singer" : ""
                                    }`}>
                                        {profile.user_type === "1" ? "Producer" : 
                                         profile.user_type === "2" ? "Musician" : 
                                         profile.user_type === "3" ? "Singer" : "Artist"}
                                    </span>
                                )}
                            </div>
                            <p className="profile-bio">{profile.bio || "No bio provided"}</p>
                            {profile.interests && profile.interests.length > 0 && (
                                <div className="profile-interests">
                                    <h4>Interests:</h4>
                                    <div className="interest-tags">
                                        {Array.isArray(profile.interests) ? 
                                            profile.interests.map((interest, i) => (
                                                <span key={i} className="interest-tag">{interest}</span>
                                            )) : 
                                            <span className="interest-tag">{String(profile.interests)}</span>
                                        }
                                    </div>
                                </div>
                            )}
                            {requestSent[profile.id] ? (
                                <button className="connect-button sent" disabled>Request Sent</button>
                            ) : (
                                <button 
                                    className="connect-button"
                                    onClick={() => handleSendFriendRequest(profile.id)}
                                >
                                    Connect
                                </button>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default ProfileList;
